<script setup lang="ts">
import {ref,computed,watch,nextTick,onUnmounted} from 'vue'
import Icon from './Icon.vue'
import Publish from './Publish.vue'
import {sections,columns,labels,fields,descriptions,type Row} from './catalog'
const selected=ref('overview'),token=ref(''),connected=ref(false),busy=ref(false),error=ref(''),syncError=ref(''),notice=ref(''),credential=ref('')
const data=ref<Record<string,Row[]>>({}),summary=ref<Row>({}),draft=ref<Row>({}),showForm=ref(false),preview=ref<Row|null>(null)
const pendingRotation=ref<Row|null>(null),pendingDelete=ref<Row|null>(null),editingID=ref(''),serverOffset=ref(0)
const search=ref(''),page=ref(0),lastUpdated=ref(0),showArchived=ref(false)
function preference(key:string,fallback:string){try{return localStorage.getItem(key)??fallback}catch{return fallback}}
const theme=ref(preference('harbor-theme','system')),refreshMode=ref(preference('harbor-refresh','eco'))
const media=window.matchMedia('(prefers-color-scheme: dark)'),systemDark=ref(media.matches)
const mediaChange=()=>{systemDark.value=media.matches};media.addEventListener('change',mediaChange)
const resolvedTheme=computed(()=>theme.value==='system'?(systemDark.value?'dark':'light'):theme.value)
watch(theme,v=>{try{localStorage.setItem('harbor-theme',v)}catch{}})
const current=computed(()=>sections.find(s=>s.key===selected.value)!)
const writable=computed(()=>!!fields[selected.value]||selected.value==='firewalls')
const sourceRows=computed(()=>data.value[selected.value]??[])
const filtered=computed(()=>sourceRows.value.filter(row=>(selected.value!=='firewalls'||showArchived.value||!row.archived_at)&&(!search.value||(JSON.stringify(row)+' '+(columns[selected.value]??[]).map(c=>display(c,row[c],row)).join(' ')).toLowerCase().includes(search.value.toLowerCase()))))
const rows=computed(()=>filtered.value.slice(page.value*15,(page.value+1)*15)),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/15)))
watch([search,showArchived],()=>{page.value=0});watch(pages,n=>{if(page.value>=n)page.value=n-1})
let session=0,etag='',sessionAbort=new AbortController(),timer:ReturnType<typeof setTimeout>|undefined
const history:Record<string,Row[]>={}
function schedule(){clearTimeout(timer);if(!connected.value||refreshMode.value==='manual'||document.visibilityState==='hidden')return;const ms=refreshMode.value==='live'?(summary.value.active_tasks?5000:15000):(summary.value.active_tasks?15000:30000);timer=setTimeout(()=>{if(!showForm.value&&!preview.value)void refresh();else schedule()},ms)}
function visibility(){if(document.visibilityState==='hidden')clearTimeout(timer);else if(connected.value)void refresh()}
document.addEventListener('visibilitychange',visibility)
let returnFocus:HTMLElement|null=null
watch([showForm,preview,pendingRotation,pendingDelete],async()=>{if(showForm.value||preview.value||pendingRotation.value||pendingDelete.value){if(!returnFocus)returnFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('[role=dialog] input,[role=dialog] select,[role=dialog] button')?.focus()}else{await nextTick();returnFocus?.focus();returnFocus=null}})
function dialogKey(e:KeyboardEvent){const dialog=document.querySelector<HTMLElement>('[role=dialog]');if(!dialog)return;if(e.key==='Escape'){showForm.value=false;preview.value=null;pendingRotation.value=null;pendingDelete.value=null;e.preventDefault()}else if(e.key==='Tab'){const focusable=Array.from(dialog.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}}
document.addEventListener('keydown',dialogKey)

watch(refreshMode,v=>{try{localStorage.setItem('harbor-refresh',v)}catch{}schedule()})
onUnmounted(()=>{clearTimeout(timer);sessionAbort.abort();document.removeEventListener('visibilitychange',visibility);document.removeEventListener('keydown',dialogKey);media.removeEventListener('change',mediaChange)})
async function api(path:string,method='GET',body?:unknown,extra:Record<string,string>={}){
 const res=await fetch('/api/v1/'+path,{method,signal:AbortSignal.any([sessionAbort.signal,AbortSignal.timeout(10000)]),headers:{Authorization:'Bearer '+token.value,'Content-Type':'application/json',...extra},body:body===undefined?undefined:JSON.stringify(body)})
 const serverDate=Date.parse(res.headers?.get('Date')??'');if(Number.isFinite(serverDate))serverOffset.value=serverDate-Date.now()
 if(res.status===304)return null
 let json:any;try{json=await res.json()}catch{throw new Error('响应无效，请检查控制面连接')}
 if(!res.ok){if(res.status===401&&connected.value){logout();syncError.value='令牌已失效，请重新登录'}throw new Error(json.error??'请求失败')}
 if(path==='snapshot')etag=res.headers?.get('ETag')??'';return json
}
async function refresh(){if(busy.value){schedule();return};const epoch=session;busy.value=true;try{const next=await api('snapshot','GET',undefined,etag?{'If-None-Match':etag}:{});if(epoch!==session)return;if(next){const collections=next.collections??{};for(const key of Object.keys(collections)){const latest=collections[key] as Row[];const seen=new Set(latest.map(r=>r.id??r.sequence));collections[key]=[...latest,...(history[key]??[]).filter(r=>!seen.has(r.id??r.sequence))].slice(0,1000)};data.value=collections;summary.value=next.summary??{}};connected.value=true;syncError.value='';lastUpdated.value=Date.now()}catch(e){if(epoch===session)syncError.value=String(e)}finally{if(epoch===session){busy.value=false;schedule()}}}
function logout(){session++;clearTimeout(timer);sessionAbort.abort();sessionAbort=new AbortController();etag='';connected.value=false;busy.value=false;token.value='';data.value={};summary.value={};credential.value='';showForm.value=false;preview.value=null;pendingRotation.value=null;pendingDelete.value=null;error.value='';syncError.value='';notice.value='';for(const k of Object.keys(history))delete history[k]}
function navigate(key:string){editingID.value='';selected.value=key;page.value=0;search.value='';showForm.value=false;preview.value=null;error.value='';notice.value=''}
async function action(work:()=>Promise<any>,success:(r:any)=>void){if(busy.value)return;const epoch=session;busy.value=true;error.value='';notice.value='';let done=false;try{const r=await work();if(epoch!==session)return;success(r);done=true}catch(e){if(epoch===session)error.value=String(e)}finally{if(epoch===session)busy.value=false};if(done&&epoch===session)await refresh()}
function openForm(){editingID.value='';error.value='';draft.value={name:'',engine:'sing-box',host_id:data.value.hosts?.[0]?.id??'',local_host:'127.0.0.1',listen_port:2080,local_port:8080,remote_port:18080,hops:[],ssh_port:22,admin_cidrs_text:'',default_action:'drop',rules:[]};showForm.value=true}
async function create(){const kind=selected.value;let path=kind,payload:Row;const editing=editingID.value;if(editing){path=kind+'/'+editing;const keys=kind==='hosts'?['name','provider','address']:kind==='nodes'?['name','engine']:['name'];payload=Object.fromEntries(keys.map(k=>[k,draft.value[k]]))}else if(kind==='firewalls'){path=`hosts/${draft.value.host_id}/firewalls`;payload={name:draft.value.name,ssh_port:draft.value.ssh_port,admin_cidrs:draft.value.admin_cidrs_text.split(/[\n,]+/).map((s:string)=>s.trim()).filter(Boolean),default_action:draft.value.default_action,rules:draft.value.rules}}else payload=Object.fromEntries(fields[kind].map(f=>[f,draft.value[f]]));await action(()=>api(path,editing?'PATCH':'POST',payload),r=>{if(r.agent_token)credential.value=JSON.stringify({HOST_ID:r.id,AGENT_TOKEN:r.agent_token},null,2);if(editing)history[kind]=(history[kind]??[]).map(row=>row.id===editing?{...row,...payload}:row);showForm.value=false;notice.value=editing?'资源已更新':kind==='firewalls'?'已保存策略版本；尚未应用到主机。':'资源已保存'})}
function editResource(row:Row){editingID.value=row.id;draft.value={...row};error.value='';showForm.value=true}
function removeResource(row:Row){const kind=selected.value;return action(()=>api(kind+'/'+row.id,'DELETE'),()=>{history[kind]=(history[kind]??[]).filter(r=>r.id!==row.id);notice.value='无依赖资源已删除，审计记录保留。'})}
function version(row:Row){return action(()=>api(`instances/${row.id}/configs`,'POST',{outbound:'block'}),()=>{notice.value='配置快照已创建，sing-box 默认阻断出站'})}
function deploy(row:Row,mode='simulation',operation='deploy'){return action(()=>api(`instances/${row.instance_id}/${operation}`,'POST',{config_id:row.config_id??row.id,mode},{'Idempotency-Key':crypto.randomUUID()}),()=>{notice.value=mode==='staging'?'校验暂存已排队，不会启动服务。':'模拟任务已排队。'})}
function viewPreview(row:Row){const firewall=selected.value==='firewalls';return action(()=>api(`${firewall?'firewalls':'configs'}/${row.id}/preview`),r=>{preview.value={...r,firewall}})}
function editFirewall(row:Row){return action(()=>api(`firewalls/${row.id}/preview`),r=>{editingID.value='';draft.value={...r.export.policy,host_id:r.export.host_id,admin_cidrs_text:r.export.policy.admin_cidrs.join('\n')};showForm.value=true})}
function archive(row:Row){return action(()=>api(`firewalls/${row.id}/archive`,'POST',{archived:!row.archived_at}),()=>{notice.value='归档状态已更新；不会改变主机上已有规则。'})}
function cancel(row:Row){return action(()=>api(`tasks/${row.id}/cancel`,'POST',{}),()=>{notice.value='尚未领取的任务已取消'})}
function rotate(row:Row){return action(()=>api(`hosts/${row.id}/rotate-agent-token`,'POST',{}),r=>{credential.value=JSON.stringify({HOST_ID:row.id,AGENT_TOKEN:r.agent_token},null,2);notice.value='旧 Agent 令牌已失效，请保存新凭据。'})}
function canRollback(row:Row){const i=data.value.instances?.find(i=>i.id===row.instance_id);return i?.staged_config_id&&i.staged_config_id!==row.id&&data.value.tasks?.some(t=>t.instance_id===row.instance_id&&t.config_id===row.id&&t.mode==='staging'&&t.state==='succeeded')}
function options(field:string){if(field==='engine')return ['sing-box','frp'].map(x=>({id:x,name:x}));if(field==='host_id')return data.value.hosts??[];if(field==='node_id')return data.value.nodes??[];return (data.value.instances??[]).filter(i=>selected.value!=='tunnels'||data.value.nodes?.find(n=>n.id===i.node_id)?.engine==='frp')}
function hostOnline(row:Row){return !!row.last_seen&&Date.now()+serverOffset.value-new Date(row.last_seen).getTime()<90000}
const names:Record<string,string>={pending:'待配置',simulated:'模拟完成',staged:'已校验暂存',queued:'排队中',running:'处理中',succeeded:'已完成',failed:'失败',cancelled:'已取消',planned:'仅规划',simulation:'模拟',staging:'校验暂存',deploy:'部署 / 暂存',rollback:'历史恢复'}
function display(field:string,value:any,row:Row={}):string{if(field==='online')return hostOnline(row)?'已连接':'未连接';if(field==='archived_at')return value?'已归档':'可用版本';if(value==null||value==='')return '—';if(['state','mode','agent_mode','operation'].includes(field))return names[value]??String(value);if(field==='result'){const r:Record<string,string>={'simulation completed; no host changes':'模拟完成，未修改主机','native configuration validated and staged; service not started':'配置已校验暂存，服务未启动','cancelled before claim':'已在领取前取消'};return r[value]??String(value)};if(['host_id','node_id','instance_id'].includes(field)){const table={host_id:'hosts',node_id:'nodes',instance_id:'instances'}[field]!;return data.value[table]?.find(r=>r.id===value)?.name??String(value).slice(0,8)};if(field.endsWith('_at')||field==='last_seen')return new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});if(field==='hops')return value.map((id:string)=>data.value.instances?.find(i=>i.id===id)?.name??id.slice(0,8)).join(' → ');return String(value)}
async function loadOlder(){const kind=selected.value;await action(()=>api(`${kind}?limit=200&offset=${data.value[kind]?.length??0}`),r=>{history[kind]=[...(data.value[kind]??[]),...r].slice(0,1000);if(!r.length)notice.value='已经载入全部历史记录'})}
function download(value:unknown,name:string){const b=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),0)}
const recentTasks=computed(()=>(data.value.tasks??[]).slice(0,5))
const ports=computed(()=>(data.value.instances?.length??0)+(data.value.tunnels?.length??0))
</script>

<template>
<div class="harbor" :data-theme="resolvedTheme">
 <div v-if="!connected" class="login"><div class="login-art"><div class="brand"><span class="brand-mark">H</span> HARBOR</div><div><span class="eyebrow">YOUR INFRASTRUCTURE, IN SYNC</span><h1>连接有序，<br>每次变更都有据。</h1><p>从主机资产到防火墙策略，<br>在一个清晰的工作空间里掌控全局。</p><div class="art-orbit"><Icon name="hosts"/><i></i><Icon name="firewalls"/><i></i><Icon name="nodes"/></div></div><small>FOUNDATION EDITION / v0.4</small></div><div class="login-card"><div class="login-top"><span class="eyebrow">WELCOME BACK</span><select v-model="theme" aria-label="主题"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></div><h2>进入工作空间</h2><p>使用本地配置中的管理员令牌登录。</p><label>管理员令牌<input v-model="token" type="password" autocomplete="off" placeholder="ADMIN_TOKEN" @keyup.enter="refresh"></label><button class="primary" :disabled="busy||!token" @click="refresh">{{busy?'正在连接…':'进入控制台'}}<Icon name="arrow"/></button><div v-if="syncError" class="error" role="alert">{{syncError}}</div><div class="login-note"><Icon name="firewalls"/>令牌只保存在当前页面内存。</div></div></div>
 <div v-else class="layout" :inert="showForm||!!preview||!!pendingRotation||!!pendingDelete">
 <aside><div class="brand"><span class="brand-mark">H</span> HARBOR</div><div class="workspace"><span class="avatar">P</span><div>个人工作空间<small>SELF / LOCAL</small></div><span class="workspace-dot"></span></div><nav><template v-for="s in sections" :key="s.key"><small v-if="s.group" class="nav-group">{{s.group}}</small><button :class="{active:selected===s.key}" :aria-current="selected===s.key?'page':undefined" @click="navigate(s.key)"><Icon :name="s.key"/><span>{{s.label}}</span><small v-if="s.key!=='overview'">{{data[s.key]?.length??0}}</small></button></template></nav><div class="aside-bottom"><span class="version-pill">FOUNDATION v0.4</span><p>更少干扰，更清晰的基础设施。</p><button @click="logout"><Icon name="logout"/>退出工作空间</button></div></aside>
 <main><header><div class="breadcrumb">工作空间<Icon name="arrow"/><b>{{current.label}}</b></div><div class="header-tools"><span class="connection-pill"><i></i>控制面已连接</span><select v-model="theme" aria-label="主题"><option value="system">跟随系统</option><option value="light">浅色主题</option><option value="dark">深色主题</option></select><button class="icon-button" aria-label="退出" @click="logout"><Icon name="logout"/></button></div></header>
 <div class="content"><div class="safety-strip"><Icon name="firewalls"/><p><b>受控变更</b>　代理默认模拟，原生配置只校验暂存；防火墙需通过 Linux 本地受限工具应用并确认。</p><span>管理端口仅限本机</span></div>
 <div class="page-heading"><div><div class="eyebrow">{{selected==='overview'?'WORKSPACE OVERVIEW':'INFRASTRUCTURE / '+selected.toUpperCase()}}</div><h1>{{current.label}}<span v-if="selected==='overview'" class="heading-dot">.</span></h1><p>{{descriptions[selected]}}</p></div><div class="actions"><button class="secondary" :disabled="busy" @click="refresh"><Icon name="refresh" :class="{spin:busy}"/>刷新</button><button v-if="writable" class="primary" @click="openForm"><Icon name="plus"/>{{selected==='firewalls'?'新建策略':'新建资源'}}</button></div></div>
 <div class="stats"><div><span class="stat-icon"><Icon name="hosts"/></span><small>主机资产</small><strong>{{summary.hosts??0}}<em>{{summary.online_hosts??0}} 台已连接</em></strong></div><div><span class="stat-icon blue"><Icon name="instances"/></span><small>部署实例</small><strong>{{summary.instances??0}}<em>独立版本管理</em></strong></div><div><span class="stat-icon amber"><Icon name="tasks"/></span><small>待处理任务</small><strong>{{summary.active_tasks??0}}<em>队列与租约保护</em></strong></div><div><span class="stat-icon violet"><Icon name="firewalls"/></span><small>防火墙策略</small><strong>{{summary.firewall_versions??0}}<em>版本化，可审查</em></strong></div></div>
 <div v-if="error" class="error" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="syncError" class="error" role="alert">同步失败：{{syncError}}</div><div v-if="notice" class="notice" role="status"><Icon name="check"/>{{notice}}</div>
 <div v-if="credential" class="secret"><b>一次性 Agent 凭据</b><p>请保存到安全位置，关闭后无法再次查看；轮换后旧令牌立即失效。</p><pre>{{credential}}</pre><button class="secondary" @click="credential=''">已保存，关闭</button></div>
 <template v-if="selected==='overview'"><div class="overview-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">HOST CONNECTIONS</span><h2>主机连接</h2></div><button class="text-button" @click="navigate('hosts')">全部主机 →</button></div><div v-if="!data.hosts?.length" class="mini-empty">先登记你的第一台主机，开始管理连接。</div><div v-for="host in (data.hosts??[]).slice(0,6)" :key="host.id" class="host-row"><span class="host-avatar"><Icon name="hosts"/></span><div><b>{{host.name}}</b><small>{{host.provider}} · {{host.address}}</small></div><span :class="['status',hostOnline(host)?'succeeded':'pending']">{{hostOnline(host)?'已连接':'未连接'}}</span></div></section><section class="panel security-card"><div class="panel-heading"><div><span class="eyebrow">SECURITY POSTURE</span><h2>安全概览</h2></div><Icon name="firewalls"/></div><div class="security-score"><span>受控模式</span><p>默认部署仅本机管理；实际生效需主机验证。</p></div><div class="security-line"><Icon name="check"/>SSH 与管理端口保护<span>策略内置</span></div><div class="security-line"><Icon name="check"/>数据库端口发布<span>默认关闭</span></div><div class="security-line"><Icon name="check"/>任务领取与完成审计<span>启用</span></div><div class="security-foot">{{ports}} 个已载入的端口预留 · {{summary.completed_tasks??0}} 项任务完成</div><button class="secondary" @click="navigate('firewalls')">管理防火墙策略<Icon name="arrow"/></button></section></div><section class="panel"><div class="panel-heading"><div><span class="eyebrow">RECENT CHANGES</span><h2>最近任务</h2></div><button class="text-button" @click="navigate('tasks')">任务中心 →</button></div><div v-if="!recentTasks.length" class="mini-empty">暂无任务。创建实例后即可生成配置并进行模拟验证。</div><div v-for="t in recentTasks" :key="t.id" class="task-row"><span :class="['task-dot',t.state]"></span><div><b>{{display('instance_id',t.instance_id)}}</b><small>{{display('mode',t.mode)}} · {{display('operation',t.operation)}}</small></div><span :class="['status',t.state]">{{display('state',t.state)}}</span><time>{{display('created_at',t.created_at)}}</time></div></section></template>
 <Publish v-else-if="selected==='publish'" :api="api" :hosts="data.hosts??[]"/>
 <section v-else class="panel table-card"><div class="table-toolbar"><div class="search-box"><Icon name="search"/><input v-model="search" placeholder="搜索已载入的名称、ID 或状态" aria-label="搜索资源"></div><div class="table-options"><label v-if="selected==='firewalls'" class="check-label"><input v-model="showArchived" type="checkbox">显示归档</label><button class="secondary" :disabled="!filtered.length" @click="download(filtered,selected+'-export.json')"><Icon name="download"/>导出</button></div></div><div class="table-scroll"><table><thead><tr><th v-for="c in columns[selected]" :key="c">{{labels[c]}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id??row.sequence"><td v-for="c in columns[selected]" :key="c" :title="display(c,row[c],row)"><span v-if="c==='state'||c==='online'" :class="['status',c==='state'?row.state:hostOnline(row)?'succeeded':'pending']">{{display(c,row[c],row)}}</span><code v-else-if="c==='checksum'||c==='resource_id'">{{display(c,row[c],row).slice(0,12)}}</code><span v-else>{{display(c,row[c],row)}}</span></td><td class="row-actions"><template v-if="fields[selected]"><button class="text-button" :disabled="busy" @click="editResource(row)">编辑</button><button class="text-button muted" :disabled="busy" @click="pendingDelete=row">删除</button></template><button v-if="selected==='instances'" class="text-button" :disabled="busy" @click="version(row)">创建配置</button><template v-else-if="selected==='configs'"><button class="text-button" :disabled="busy" @click="viewPreview(row)">预览</button><button class="text-button" :disabled="busy" @click="deploy(row)">模拟</button><button class="text-button" :disabled="busy" @click="deploy(row,'staging')">校验暂存</button><button v-if="canRollback(row)" class="text-button" :disabled="busy" @click="deploy(row,'staging','rollback')">历史恢复</button></template><template v-else-if="selected==='firewalls'"><button class="text-button" :disabled="busy" @click="viewPreview(row)">预览 / 下载</button><button class="text-button" :disabled="busy" @click="editFirewall(row)">新版本</button><button class="text-button muted" :disabled="busy" @click="archive(row)">{{row.archived_at?'恢复归档':'归档'}}</button></template><template v-else-if="selected==='tasks'"><button v-if="row.state==='queued'" class="text-button" :disabled="busy" @click="cancel(row)">取消排队</button><button v-if="['failed','cancelled'].includes(row.state)" class="text-button" :disabled="busy" @click="deploy(row,row.mode,row.operation??'deploy')">重试</button></template><button v-else-if="selected==='hosts'" class="text-button" :disabled="busy" @click="pendingRotation=row">轮换令牌</button><code v-else>{{(row.id??String(row.sequence)).slice(0,8)}}</code></td></tr></tbody></table></div><div v-if="!rows.length" class="empty"><span><Icon :name="selected"/></span><h3>{{search?'未找到匹配记录':'从第一项资源开始'}}</h3><p>{{search?'试试其他名称或 ID。':writable?'创建资源后，即可在这里查看和管理。':'完成配置或提交任务后，记录会显示在这里。'}}</p></div><div class="pagination"><small>已载入 {{sourceRows.length}} 条 · 筛选 {{filtered.length}} 条</small><div><button class="secondary" :disabled="page===0" @click="page--">上一页</button><span>{{page+1}} / {{pages}}</span><button class="secondary" :disabled="page+1>=pages" @click="page++">下一页</button><button v-if="sourceRows.length>=200&&sourceRows.length<1000" class="text-button" :disabled="busy" @click="loadOlder">载入更早记录</button></div></div></section>
 <footer><span><i></i>最近同步 {{lastUpdated?new Date(lastUpdated).toLocaleTimeString('zh-CN'):'—'}}</span><label>自动刷新<select v-model="refreshMode" aria-label="自动刷新"><option value="eco">节能</option><option value="live">实时</option><option value="manual">手动</option></select></label><small>切到后台自动暂停 · HARBOR v0.4</small></footer>
 </div></main></div>
 <div v-if="pendingDelete" class="modal-backdrop" @click.self="pendingDelete=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="delete-title"><div class="modal-heading"><h2 id="delete-title">删除无依赖资源</h2><button class="icon-button" aria-label="关闭删除确认" @click="pendingDelete=null"><Icon name="close"/></button></div><div class="form-content"><p>确认删除 {{pendingDelete.name}}？删除后无法恢复，审计记录会保留。存在配置历史、策略或其他引用的资源会被拒绝删除。</p></div><div class="modal-footer"><button class="secondary" @click="pendingDelete=null">保留资源</button><button class="primary" :disabled="busy" @click="removeResource(pendingDelete);pendingDelete=null">确认删除</button></div></section></div>
 <div v-if="pendingRotation" class="modal-backdrop" @click.self="pendingRotation=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="rotate-title"><div class="modal-heading"><h2 id="rotate-title">轮换 Agent 令牌</h2><button class="icon-button" aria-label="关闭确认" @click="pendingRotation=null"><Icon name="close"/></button></div><div class="form-content"><p>主机 {{pendingRotation.name}} 的旧令牌会立即失效，Agent 会断开。请保存新凭据，并更新对应主机的 Agent 配置。</p></div><div class="modal-footer"><button class="secondary" @click="pendingRotation=null">暂不轮换</button><button class="primary" :disabled="busy" @click="rotate(pendingRotation);pendingRotation=null">确认轮换</button></div></section></div>
 <div v-if="showForm" class="modal-backdrop" @click.self="showForm=false" @keydown.esc="showForm=false"><form class="resource-form modal" role="dialog" aria-modal="true" aria-labelledby="form-title" @submit.prevent="create"><div class="modal-heading"><div><span class="eyebrow">CREATE / VERSIONED CHANGE</span><h2 id="form-title">{{editingID?'修改'+current.label:selected==='firewalls'?'创建防火墙策略版本':'新建'+current.label}}</h2></div><button type="button" class="icon-button" aria-label="关闭表单" @click="showForm=false"><Icon name="close"/></button></div><div class="form-content"><div v-if="error" class="error" role="alert">{{error}}</div><template v-if="selected==='firewalls'"><div class="form-note"><Icon name="firewalls"/>策略保存不等于应用。SSH 白名单、回环访问和管理端口保护始终保留。</div><div class="fields"><label>策略名称<input v-model="draft.name" required maxlength="100" placeholder="例如：基础代理入站"></label><label>所属主机<select v-model="draft.host_id" required><option v-for="h in data.hosts" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>SSH 端口<input v-model.number="draft.ssh_port" type="number" min="1" max="65535" required></label><label>其他入站流量<select v-model="draft.default_action"><option value="drop">默认拒绝（推荐）</option><option value="accept">默认允许</option></select></label></div><label class="wide-field">管理员来源 CIDR<textarea v-model="draft.admin_cidrs_text" required placeholder="填写你的固定管理 IP，例如 203.0.113.10/32；每行一个。不要填 0.0.0.0/0。"></textarea><small>同时使用 IPv6 SSH 时也要加入对应 IPv6 网段。</small></label><div class="rules-heading"><h3>自定义入站规则 <span>{{draft.rules.length}} / 128</span></h3><button class="secondary" type="button" :disabled="draft.rules.length>=128" @click="draft.rules.push({name:'',protocol:'tcp',port:2080,end_port:0,source:'0.0.0.0/0',action:'accept'})"><Icon name="plus"/>添加规则</button></div><div v-for="(r,index) in draft.rules" :key="Number(index)" class="firewall-rule"><label>备注<input v-model="r.name" maxlength="100" placeholder="代理入口"></label><label>协议<select v-model="r.protocol"><option>tcp</option><option>udp</option></select></label><label>起始端口<input v-model.number="r.port" type="number" min="1" max="65535" required></label><label>结束端口<input v-model.number="r.end_port" type="number" min="0" max="65535" placeholder="0 表示单端口"></label><label class="source-field">来源 CIDR<input v-model="r.source" required placeholder="0.0.0.0/0"></label><label>动作<select v-model="r.action"><option value="accept">允许</option><option value="drop">拒绝</option></select></label><button class="icon-button" type="button" aria-label="删除规则" @click="draft.rules.splice(Number(index),1)"><Icon name="close"/></button></div><p class="muted">拒绝规则优先于允许。SSH、22、8080 和 5173 不接受自定义规则。</p></template>
 <div v-else class="fields"><label v-for="f in (editingID?(selected==='hosts'?['name','provider','address']:selected==='nodes'?['name','engine']:['name']):fields[selected])" :key="f" :class="{'full-field':f==='hops'}">{{labels[f]}}<div v-if="f==='hops'" class="hop-editor"><div v-for="(_,index) in draft.hops" :key="Number(index)" class="hop-row"><span>{{Number(index)+1}}</span><select v-model="draft.hops[index]" required><option disabled value="">选择实例</option><option v-for="o in options('hops').filter(i=>data.nodes?.find(n=>n.id===i.node_id)?.engine==='sing-box')" :key="o.id" :value="o.id">{{o.name}}</option></select><button type="button" class="icon-button" @click="draft.hops.splice(Number(index),1)"><Icon name="close"/></button></div><button type="button" class="secondary" :disabled="draft.hops.length>=8" @click="draft.hops.push('')">＋ 添加一跳</button><small>需要 2–8 个不同实例，按编号顺序保存。</small></div><select v-else-if="['engine','host_id','node_id','instance_id'].includes(f)" v-model="draft[f]" required><option v-for="o in options(f)" :key="o.id" :value="o.id">{{o.name}}</option></select><input v-else-if="f.endsWith('port')" v-model.number="draft[f]" type="number" :min="f==='local_port'?1:1024" max="65535" required><input v-else v-model="draft[f]" :placeholder="f==='address'?'仅作库存记录，不会自动连接':''" required maxlength="255"></label></div>
 </div><div class="modal-footer"><button type="button" class="secondary" @click="showForm=false">取消</button><button class="primary" :disabled="busy">{{busy?'正在保存…':editingID?'保存修改':'保存'+(selected==='firewalls'?'策略版本':'资源')}}</button></div></form></div>
 <div v-if="preview" class="modal-backdrop" @click.self="preview=null" @keydown.esc="preview=null"><section class="modal preview-modal" role="dialog" aria-modal="true" aria-labelledby="preview-title"><div class="modal-heading"><div><span class="eyebrow">REVIEW BEFORE CHANGE</span><h2 id="preview-title">{{preview.firewall?'防火墙规则预览':'原生配置预览'}}</h2></div><button class="icon-button" aria-label="关闭预览" @click="preview=null"><Icon name="close"/></button></div><div class="form-content"><div class="form-note"><Icon name="firewalls"/>{{preview.firewall?'仅管理自有 INPUT 表。不会覆盖其他防火墙；不涵盖云安全组、Docker 转发、NAT 或出站规则。':'凭据已隐藏，仅用于回环实验。配置暂存不会启动服务。'}}</div><template v-if="preview.firewall"><h3>SSH 保护与入站规则</h3><pre class="native-preview">{{preview.nft}}</pre></template><div v-for="file in preview.files??[]" :key="file.name"><h3>{{file.name}}</h3><pre class="native-preview">{{JSON.stringify(file.content,null,2)}}</pre></div></div><div class="modal-footer"><button class="secondary" @click="preview=null">关闭</button><button v-if="preview.firewall" class="primary" @click="download(preview.export,'harbor-firewall-policy.json')"><Icon name="download"/>下载受限工具策略</button></div></section></div>
</div>
</template>
